function solve(input) {
  const seen = new Set();
  const balances = new Map();

  for (const { eventId, account, delta } of input) {
    if (seen.has(eventId)) {
      continue;
    }
    seen.add(eventId);
    balances.set(account, (balances.get(account) || 0) + delta);
  }

  const result = Array.from(balances);
  result.sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
  });

  return result;
}

